-- Source: supplied landtagsabgeordnete_bw_mit_wahlergebnissen_1952_2026.xlsx,
-- sheet Wahlperioden. Explicit period supplement; result imports stay independent.
BEGIN;
INSERT INTO public.election_analysis_period_proposals AS existing
(period_number,election_year,election_date,starts_on,ends_on,expected_ends_on,election_source_url,term_source_url,verified,notes)
SELECT period_number,election_year,election_date,starts_on,ends_on,expected_ends_on,election_source_url,term_source_url,true,notes
FROM jsonb_to_recordset($period_data$[{"period_number":1,"election_year":1952,"election_date":"1952-03-09","starts_on":"1952-03-25","ends_on":"1956-03-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/resource/blob/618426/0fbd0f925d6293b2ad676a2761069f3f/17_0139_28012026.pdf","notes":"Beginn der Verfassunggebenden Landesversammlung; ab 19.11.1953 erster Landtag."},{"period_number":2,"election_year":1956,"election_date":"1956-03-04","starts_on":"1956-04-01","ends_on":"1960-03-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/resource/blob/618426/0fbd0f925d6293b2ad676a2761069f3f/17_0139_28012026.pdf","notes":"Sonderregelung: vor der 3. Wahlperiode lagen April und Mai 1960."},{"period_number":3,"election_year":1960,"election_date":"1960-05-15","starts_on":"1960-06-01","ends_on":"1964-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":"Wiederholungswahl am 12.03.1961 in zwei Wahlkreisen."},{"period_number":4,"election_year":1964,"election_date":"1964-04-26","starts_on":"1964-06-01","ends_on":"1968-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":5,"election_year":1968,"election_date":"1968-04-28","starts_on":"1968-06-01","ends_on":"1972-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":6,"election_year":1972,"election_date":"1972-04-23","starts_on":"1972-06-01","ends_on":"1976-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":7,"election_year":1976,"election_date":"1976-04-04","starts_on":"1976-06-01","ends_on":"1980-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":8,"election_year":1980,"election_date":"1980-03-16","starts_on":"1980-06-01","ends_on":"1984-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":9,"election_year":1984,"election_date":"1984-03-25","starts_on":"1984-06-01","ends_on":"1988-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":10,"election_year":1988,"election_date":"1988-03-20","starts_on":"1988-06-01","ends_on":"1992-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":11,"election_year":1992,"election_date":"1992-04-05","starts_on":"1992-06-01","ends_on":"1996-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":12,"election_year":1996,"election_date":"1996-03-24","starts_on":"1996-06-01","ends_on":"2001-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":"Erste regulär fünfjährige Wahlperiode."},{"period_number":13,"election_year":2001,"election_date":"2001-03-25","starts_on":"2001-06-01","ends_on":"2006-05-31","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":14,"election_year":2006,"election_date":"2006-03-26","starts_on":"2006-06-01","ends_on":"2011-04-30","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":"Wahlperiode wegen Verfassungsänderung 2008 um einen Monat verkürzt."},{"period_number":15,"election_year":2011,"election_date":"2011-03-27","starts_on":"2011-05-01","ends_on":"2016-04-30","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":16,"election_year":2016,"election_date":"2016-03-13","starts_on":"2016-05-01","ends_on":"2021-04-30","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":17,"election_year":2021,"election_date":"2021-03-14","starts_on":"2021-05-01","ends_on":"2026-04-30","expected_ends_on":null,"election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":null},{"period_number":18,"election_year":2026,"election_date":"2026-03-08","starts_on":"2026-05-01","ends_on":null,"expected_ends_on":"2031-04-30","election_source_url":"https://www.bundeswahlleiterin.de/service/landtagswahlen/land-8.html","term_source_url":"https://www.landtag-bw.de/files/live/sites/LTBW/files/dokumente/rechtliche_grundlagen/Landesverfassung.pdf","notes":"Reguläres, noch zukünftiges Ende; vorbehaltlich vorzeitiger Auflösung."}]$period_data$::jsonb) AS x(
period_number integer,election_year integer,election_date date,starts_on date,ends_on date,
expected_ends_on date,election_source_url text,term_source_url text,notes text)
ON CONFLICT(period_number) DO UPDATE SET
 starts_on=coalesce(existing.starts_on,excluded.starts_on),
 ends_on=coalesce(existing.ends_on,excluded.ends_on),
 expected_ends_on=coalesce(existing.expected_ends_on,excluded.expected_ends_on),
 term_source_url=CASE WHEN existing.starts_on IS NULL AND existing.ends_on IS NULL
 THEN excluded.term_source_url ELSE existing.term_source_url END,
 notes=CASE WHEN existing.starts_on IS NULL AND existing.ends_on IS NULL
 THEN excluded.notes ELSE existing.notes END
WHERE existing.verified AND existing.election_year=excluded.election_year
 AND existing.election_date=excluded.election_date;

-- Fill missing history fields only. Existing inheritance/validation triggers remain active.
UPDATE public.election_history_periods p SET
 election_year=coalesce(p.election_year,s.election_year),
 election_date=coalesce(p.election_date,s.election_date),
 starts_on=coalesce(p.starts_on,s.starts_on),
 ends_on=coalesce(p.ends_on,s.ends_on,s.expected_ends_on),
 expected_ends_on=coalesce(p.expected_ends_on,s.expected_ends_on),
 source_url=coalesce(nullif(p.source_url,''),s.term_source_url)
FROM public.election_analysis_period_proposals s
WHERE p.number=s.period_number AND s.verified
 AND (p.election_year IS NULL OR p.election_year=s.election_year)
 AND (p.election_date IS NULL OR p.election_date=s.election_date)
 AND (p.starts_on IS NULL OR p.starts_on=s.starts_on)
 AND (p.ends_on IS NULL OR p.ends_on=coalesce(s.ends_on,s.expected_ends_on));
CREATE OR REPLACE FUNCTION public.apply_verified_election_period(period_number_to_apply integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE proposal public.election_analysis_period_proposals; current_row public.election_history_periods; changed public.election_history_periods;
BEGIN
 IF NOT public.is_superadmin(auth.uid()) THEN RAISE EXCEPTION 'Nur Super-Admins' USING ERRCODE='42501'; END IF;
 SELECT * INTO proposal FROM public.election_analysis_period_proposals WHERE period_number=period_number_to_apply AND verified;
 IF NOT FOUND THEN RAISE EXCEPTION 'Kein amtlich bestätigter Terminvorschlag'; END IF;
 SELECT * INTO current_row FROM public.election_history_periods WHERE number=period_number_to_apply FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Legislaturperiode fehlt'; END IF;
 IF current_row.election_year IS NOT NULL AND current_row.election_year<>proposal.election_year THEN RAISE EXCEPTION 'Vorhandenes Wahljahr widerspricht dem Vorschlag; zuerst manuell prüfen'; END IF;
 -- Fill only missing values; never replace already entered/confirmed dates.
 UPDATE public.election_history_periods SET
  election_year=coalesce(election_year,proposal.election_year),election_date=coalesce(election_date,proposal.election_date),
  starts_on=coalesce(starts_on,proposal.starts_on),ends_on=coalesce(ends_on,proposal.ends_on,proposal.expected_ends_on),
  expected_ends_on=coalesce(expected_ends_on,proposal.expected_ends_on),source_url=coalesce(nullif(source_url,''),nullif(proposal.term_source_url,''),proposal.election_source_url)
 WHERE id=current_row.id RETURNING * INTO changed;
 RETURN jsonb_build_object('before',to_jsonb(current_row),'after',to_jsonb(changed),'existing_dates_preserved',true);
END $$;
COMMIT;
